 function appField(f:AppField,value:unknown=''):string{
  const name='custom_'+f.key;let initial=value===null||value===undefined?'':String(value);
  if(f.type==='boolean')return `<div><label for="custom-${f.key}">${e(f.label)}</label><select id="custom-${f.key}" name="${name}" ${f.required?'required':''}><option value="">Choose…</option><option value="true" ${value===true?'selected':''}>Yes</option><option value="false" ${value===false?'selected':''}>No</option></select></div>`;
  if(f.type==='choice'||f.type==='customer')return select(name,e(f.label),[['','Choose…'],...(f.type==='customer'?customers.map(c=>[c.id,c.name]):f.options!.map(o=>[o,o]))],initial,false).replace('<select ','<select '+(f.required?'required ':''));
  if(f.type==='longtext')return area(name,e(f.label),initial,f.required);
  if(f.type==='money'&&initial!=='')initial=(Number(value)/100).toFixed(2);
  return field(name,e(f.label),f.type==='money'||f.type==='number'?'number':f.type==='date'?'date':'text',initial,{required:f.required,step:f.type==='money'?'.01':f.type==='number'?'any':undefined,min:f.type==='money'?0:undefined,maxlength:500});
 }
